const ui={storageConflict:false,backgroundEditorPageId:null,backgroundAdjustment:null,pendingNext:null,returnToReview:false,page:'home',homeTab:'cases',query:'',filter:'all',step:1,pageId:null,scope:'page',prompt:'',backgroundPrompt:'',adjustment:null,error:'',busy:null,jobTimer:null,voiceProgress:null,voiceTimer:null,failAI:false,failAssets:false,failSave:false,navigationExpanded:false,play:null,dialogMode:null,returnFocus:null,scroll:0,hasExpanded:false};
