function editorWorkspace(){syncContentPage();syncBackgroundPage();return {step:ui.step===5?(ui.reviewOriginStep||3):ui.step,pageId:ui.pageId,scope:ui.scope,prompt:ui.prompt,backgroundPrompt:ui.backgroundPrompt,...(state.draft&&ui.adjustment?{adjustment:clone(ui.adjustment)}:{}),...(state.draft&&ui.backgroundAdjustment?{backgroundAdjustment:clone(ui.backgroundAdjustment)}:{}),...(!state.draft?{form:clone(settings)}:{})};}
