  if(state.draft&&!ui.adjustment){const kind=ui.scope==='course'?'course':'page',pageId=kind==='course'?null:ui.pageId||state.draft.pages[0].id;ui.adjustment={open:!!ui.prompt,kind,pageId,drafts:ui.prompt?[{kind,pageId,prompt:ui.prompt}]:[]};}
