  const owner=side==='before'?state.published?.course:state.draft,page=owner?.pages.find(p=>p.id===pageId),details=$('#review-evidence-'+pageId);
  if(wasPlaying||ui.step!==5||ui.page!=='editor'||ui.play||!details?.open||!page||pageAssetStatus(page,'voice',{draft:owner})!=='ready')return;
  const token=reviewRun,courseId=activeId;reviewSpeech={pageId,side,token,status:'starting'};
