  const u=ui.play;if(!u?.published||u.caseId||u.ownerId!==activeId)return true;
  try{const record=L.get(library,activeId),classrooms={...(record.classrooms||{}),[u.sessionKey]:{index:u.index,ended:!!u.ended,roundId:u.roundId,updatedAt:new Date().toISOString()}};persistRecord({...record,classrooms,updatedAt:new Date().toISOString()});u.sessionSaved=true;return true;}
