  const saved=savedClassroom();
  if(saved&&!mode){showDialog('开始授课 · V'+state.published.version,`<p>上次${saved.ended?'已完成本轮课程':`停在第 ${saved.index+1} 页「${E(state.published.course.pages[saved.index].title)}」`}。</p>`,btn('取消','close-dialog')+btn('开始新一轮','classroom-new','secondary')+btn('继续上次','classroom-continue','primary'));return;}
  closeDialog();startPreview(true,true);if(!ui.play?.published)return;
  ui.play.sessionKey=classroomVersionKey();ui.play.roundId=mode==='continue'&&saved?saved.roundId:Date.now().toString(36);
